fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    assert!(m > 0 && n > 0, "inputs must be non-empty");
    assert!(
        m == n || m == 1 || n == 1,
        "inputs must be broadcast-compatible"
    );

    let out_len = m.max(n);

    // Helper: expand an input to `out_len` under the broadcasting rule.
    fn broadcast_to(v: &Vec<i8>, out_len: usize) -> Vec<i8> {
        if v.len() == 1 {
            vec![v[0]; out_len]
        } else {
            debug_assert_eq!(v.len(), out_len);
            v.clone()
        }
    }

    let out_a = broadcast_to(&a, out_len);
    let out_b = broadcast_to(&b, out_len);

    (out_a, out_b)
}